class Solution:
    def maximumBalancedSubarrayLength(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            x = e = o = 0
            for j in range(i, n):
                x ^= nums[j]
                if nums[j] % 2 == 0:
                    e += 1
                else:
                    o += 1
                if x == 0 and e == o:
                    ans = max(ans, j - i + 1)
        return ans

