        for (int i = 0; i < n; i++) {
            int x = 0, e = 0, o = 0;
            for (int j = i; j < n; j++) {
                x ^= nums[j];
                nums[j] % 2 == 0 ? e++ : o++;
                if (x == 0 && e == o) ans = max(ans, j - i + 1);
            }
        }
        return ans;
    }
};

