class Solution:
    def maximumBalancedSubarrayLength(self, nums: List[int]) -> int:
        first = {(0, 0): -1}
        x = bal = ans = 0
        for j, v in enumerate(nums):
            x ^= v
            bal += 1 if v % 2 == 0 else -1
            key = (x, bal)
            if key in first:
                ans = max(ans, j - first[key])
            else:
                first[key] = j
        return ans

