class Solution {
public:
    int maximumBalancedSubarrayLength(vector<int>& nums) {
        unordered_map<long long, int> first;
        first[0LL] = -1;
        long long x = 0;
        int bal = 0, ans = 0;
        for (int j = 0; j < (int)nums.size(); j++) {
            x ^= nums[j];
            bal += (nums[j] % 2 == 0) ? 1 : -1;
            long long key = x * 400001LL + (bal + 200000);
            auto it = first.find(key);
            if (it != first.end()) ans = max(ans, j - it->second);
            else first[key] = j;
        }
        return ans;
    }
};

