class Solution {
    public int maximumBalancedSubarrayLength(int[] nums) {
        Map<Long, Integer> first = new HashMap<>();
        first.put(0L, -1);
        long x = 0;
        int bal = 0, ans = 0;
        for (int j = 0; j < nums.length; j++) {
            x ^= nums[j];
            bal += (nums[j] % 2 == 0) ? 1 : -1;
            long key = x * 400001L + (bal + 200000);
            Integer idx = first.get(key);
            if (idx != null) ans = Math.max(ans, j - idx);
            else first.put(key, j);
        }
        return ans;
    }
}

